  /**
   * The person's timeline: one line per dated thing about them, by date, and on a date their grade
   * changes, then claims (by amount), then holds, then retirements, then unretirements.
   */
  protected timelineOf(p: Person): string[] {
    const lines: { date: string; rank: number; order: number; text: string }[] = [];
    for (const g of p.grades) {
      if (g.from !== null) lines.push({ date: g.from, rank: 0, order: 0, text: `grade ${g.grade}` });
    }
    for (const c of this.claimsOf(p.id)) {
      lines.push({ date: c.date, rank: 1, order: cents(c.amount) * 1e9 + c.id, text: `claim ${c.amount} ${c.status}` });
    }
    for (const h of p.holds) {
      lines.push({ date: h.from, rank: 2, order: 0, text: h.to !== null ? `hold to ${h.to}` : 'hold' });
    }
    for (const r of p.retirements) {
      lines.push({ date: r.from, rank: 3, order: 0, text: 'retired' });
      lines.push({ date: r.to, rank: 4, order: 0, text: 'unretired' });
